Here is a suggested Python script to solve the problem:

```python
import itertools

def valid_distributions():
    """Yield all triples (a,b,c) of non-negative integers summing to 30 satisfying constraints."""
    total = 30
    for a in range(total+1):
        for b in range(total+1 - a):
            c = total - a - b
            # constraint: at least one box has at least 2 coins
            if not (a >= 2 or b >= 2 or c >= 2):
                continue
            # constraint: there exist two boxes with difference exactly 6 (positive difference)
            if any(abs(x - y) == 6 for x,y in [(a,b),(a,c),(b,c)]):
                yield (a,b,c)

def total_winnings(guess, actual, perm):
    """Given guess triple (g1,g2,g3), actual triple (a1,a2,a3), and permutation perm (list of indices),
    compute total coins won."""
    total = 0
    for i in range(3):
        g = guess[perm[i]]
        a = actual[i]
        if g <= a:
            total += g
    return total

def worst_case_for_distribution(guess, actual):
    """Given guess triple and actual triple, return minimum total winnings over all permutations."""
    min_w = float('inf')
    for perm in itertools.permutations([0,1,2]):
        w = total_winnings(guess, actual, perm)
        if w < min_w:
            min_w = w
    return min_w

def worst_case_overall(guess):
    """Given guess triple, return minimum total winnings over all valid distributions."""
    min_total = float('inf')
    for actual in valid_distributions():
        w = worst_case_for_distribution(guess, actual)
        if w < min_total:
            min_total = w
    return min_total

