                elif w == best_worst:
                    best_guesses.append(guess)

    print("Optimal guessing strategy (sorted guesses):")
    for guess in best_guesses:
        print(f"  {guess}")
    print(f"Guaranteed minimum coins won: {best_worst}")
    print(f"Minimum amount of money: ${best_worst * 1000}")

    # Additional analysis: show worst-case distribution for optimal guess
    if best_guesses:
        guess = best_guesses[0]
        worst_distributions = []
        min_w = float('inf')
        for actual in valid_distributions():
            w = worst_case_for_distribution(guess, actual)
