                min_w = w
                worst_distributions = [actual]
            elif w == min_w:
                worst_distributions.append(actual)
        print(f"\nFor optimal guess {guess}, worst-case distributions (actual coin counts):")
        for d in worst_distributions[:10]:  # limit output
            print(f"  {d}")
        print(f"(Total {len(worst_distributions)} such distributions yield {min_w} coins.)")

if __name__ == "__main__":
    main()
